-- Disposable ONLY; every identity, header-free digest and credential placeholder is synthetic.
begin;
create function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'MAIL 5A TEST: %',label;end if;end$$;
create function pg_temp.denied(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when insufficient_privilege or unique_violation then return true;end$$;
insert into public.app_members(email,is_active) values('mail.one@synthetic.test',true),('mail.two@synthetic.test',true),('mail.noperm@synthetic.test',true),('mail.inactive@synthetic.test',false);
insert into public.member_permissions(email,permission) values('mail.one@synthetic.test','mail_completion'),('mail.two@synthetic.test','mail_completion');
insert into public.google_mailbox_connections(email,granted_scopes,refresh_token_encrypted,refresh_token_iv,refresh_token_tag)
 select email,array['https://www.googleapis.com/auth/gmail.modify','https://www.googleapis.com/auth/gmail.readonly'],'synthetic-cipher','synthetic-iv','synthetic-tag' from public.app_members where email in ('mail.one@synthetic.test','mail.two@synthetic.test');
create temp table mail_ctx(v jsonb);grant all on mail_ctx to authenticated;
set local role anon;
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_context()$q$),'anon denied');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.stranger@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_state()$q$),'nonmember denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.inactive@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.list_mail_reviews()$q$),'inactive denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.one@synthetic.test"}',true);
select pg_temp.expect(not public.mail_completion_state(),'off by default');
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_context()$q$),'flag blocks dispatch');
reset role;
update private.mail_completion_configuration set enabled=true;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.noperm@synthetic.test"}',true);
select pg_temp.expect(not public.mail_completion_state(),'canonical permission absent');
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_context()$q$),'permissionless denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.one@synthetic.test"}',true);
insert into mail_ctx select public.mail_completion_context();
select public.create_mail_review('f5000000-0000-0000-0000-000000000001','send',repeat('a',64),(select v->>'connectionRevision' from mail_ctx),'synthetic-draft-1');
select pg_temp.expect(public.create_mail_review('f5000000-0000-0000-0000-000000000001','send',repeat('a',64),(select v->>'connectionRevision' from mail_ctx),'synthetic-draft-1')='f5000000-0000-0000-0000-000000000001','create idempotent');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000001','completed')$q$),'cannot skip claim');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000001','claim',repeat('b',64))$q$),'stale content denied');
select pg_temp.expect(public.advance_mail_review('f5000000-0000-0000-0000-000000000001','claim',repeat('a',64))='claimed','claim');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000001','claim',repeat('a',64))$q$),'claim never reissued');
select pg_temp.expect(public.advance_mail_review('f5000000-0000-0000-0000-000000000001','cancel')='cancelled','cancel mid-roundtrip before dispatch');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000001','dispatch',repeat('a',64))$q$),'cancel wins dispatch fence');
select public.create_mail_review('f5000000-0000-0000-0000-000000000002','send',repeat('a',64),(select v->>'connectionRevision' from mail_ctx),'synthetic-draft-1');
select public.advance_mail_review('f5000000-0000-0000-0000-000000000002','claim',repeat('a',64));
select public.advance_mail_review('f5000000-0000-0000-0000-000000000002','dispatch',repeat('a',64));
select pg_temp.expect(public.advance_mail_review('f5000000-0000-0000-0000-000000000002','cancel')='uncertain','late cancel never claims no delivery');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000002','claim',repeat('a',64))$q$),'uncertain cannot retry');
select pg_temp.expect(pg_temp.denied($q$select public.create_mail_review('f5000000-0000-0000-0000-000000000003','send',repeat('b',64),(select v->>'connectionRevision' from mail_ctx),'synthetic-draft-1')$q$),'uncertain draft cannot obtain another send review');
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.two@synthetic.test"}',true);
select pg_temp.expect((select count(*)=0 from public.list_mail_reviews()),'owner isolation');
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000002','cancel')$q$),'cannot cancel another owner');
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.one@synthetic.test"}',true);
select public.create_mail_review('f5000000-0000-0000-0000-000000000004','save',repeat('a',64),(select v->>'connectionRevision' from mail_ctx),null);
select public.advance_mail_review('f5000000-0000-0000-0000-000000000004','claim',repeat('a',64));
reset role;
-- Same transaction/updated_at: epoch includes cipher/scopes, not timestamp alone.
update public.google_mailbox_connections set refresh_token_encrypted='synthetic-rotated',granted_scopes=array['https://www.googleapis.com/auth/gmail.readonly'] where email='mail.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000004','dispatch',repeat('a',64))$q$),'scope revocation fences write');
reset role;
update public.google_mailbox_connections set granted_scopes=array['https://www.googleapis.com/auth/gmail.modify'] where email='mail.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.advance_mail_review('f5000000-0000-0000-0000-000000000004','dispatch',repeat('a',64))$q$),'reconnect invalidates previous review');
reset role;
-- DELETE: disposable synthetic connection only, simulating disconnect.
delete from public.google_mailbox_connections where email='mail.one@synthetic.test';
set local role authenticated;
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_context()$q$),'connection revoked');
select pg_temp.expect(public.advance_mail_review('f5000000-0000-0000-0000-000000000004','cancel')='cancelled','can cancel own pre-dispatch review after disconnect');
reset role;
insert into auth.users(id,email) values('f5000000-0000-0000-0000-000000000099','mail.service@synthetic.test');
insert into private.machine_identities(sub,enabled,relationships_only) values('f5000000-0000-0000-0000-000000000099',true,true);
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"f5000000-0000-0000-0000-000000000099","email":"mail.service@synthetic.test"}',true);
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_state()$q$),'machine state denied');
select pg_temp.expect(pg_temp.denied($q$select public.mail_completion_context()$q$),'machine context denied');
select pg_temp.expect(pg_temp.denied($q$select public.list_mail_reviews()$q$),'machine reviews denied');
select pg_temp.expect(pg_temp.denied($q$select private.mail_schedule_next('pending','claim')$q$),'machine scheduling denied');
select pg_temp.expect(pg_temp.denied($q$select * from private.mail_mutation_reviews$q$),'no direct table read');
select pg_temp.expect(pg_temp.denied($q$insert into private.mail_completion_configuration values(false,true)$q$),'no direct config writes');
reset role;
insert into public.google_mailbox_connections(email,granted_scopes,refresh_token_encrypted,refresh_token_iv,refresh_token_tag) values('mail.one@synthetic.test',array['https://www.googleapis.com/auth/gmail.modify'],'synthetic','synthetic','synthetic');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"mail.one@synthetic.test"}',true);
select pg_temp.expect(private.mail_schedule_next('pending','claim')='claimed','schedule model claim');
select pg_temp.expect(private.mail_schedule_next('pending','cancel')='cancelled','schedule model cancel');
select pg_temp.expect(private.mail_schedule_next('claimed','confirmed',true)='sent','schedule model confirmed');
select pg_temp.expect(private.mail_schedule_next('claimed','lost_result',true)='uncertain','schedule uncertain');
select pg_temp.expect(private.mail_schedule_next('claimed','cancel',false)='cancelled','schedule predispatch cancellation');
select pg_temp.expect(private.mail_schedule_next('claimed','cancel',true)='uncertain','schedule postdispatch cancellation');
select pg_temp.expect(pg_temp.denied($q$select private.mail_schedule_next('uncertain','claim')$q$),'scheduled uncertain terminal');
select pg_temp.expect(pg_temp.denied($q$select private.mail_schedule_next('sent','claim')$q$),'sent terminal');
select pg_temp.expect(pg_temp.denied($q$select private.mail_schedule_next('pending','confirmed',true)$q$),'no pending to sent');
reset role;
select pg_temp.expect(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('mail_completion_context','mail_completion_state','create_mail_review','advance_mail_review','list_mail_reviews') and p.prosecdef),'public RPCs invoker');
select pg_temp.expect((select count(*)=4 from pg_policy where polname='machine_identity_isolation' and polrelid in('private.mail_completion_configuration'::regclass,'private.mail_completion_baseline'::regclass,'private.mail_mutation_reviews'::regclass,'private.mail_scheduled_design'::regclass) and pg_get_expr(polqual,polrelid) like '%SELECT%' and pg_get_expr(polwithcheck,polrelid) like '%SELECT%'),'all new tables isolated via InitPlan');
select pg_temp.expect(not exists(select 1 from information_schema.columns where table_schema='private' and table_name in ('mail_mutation_reviews','mail_scheduled_design') and column_name in ('body','html','mime','payload','recipients','alias','subject','resumable_url')),'no content or resumable URL store');
-- Synthetic backlog: expiry work is bounded too, not only the returned history.
insert into private.mail_mutation_reviews(id,owner_email,operation,revision,connection_revision,state,created_at,expires_at,dispatch_started_at)
select md5('synthetic-expired-'||n)::uuid,'mail.one@synthetic.test','save',repeat('a',64),'synthetic','claimed',now()-interval '20 minutes',now()-interval '11 minutes',now()-interval '19 minutes' from generate_series(1,125)n;
set local role authenticated;
select pg_temp.expect((select count(*)=25 from public.list_mail_reviews()),'history response bounded');
reset role;
select pg_temp.expect((select count(*)=25 from private.mail_mutation_reviews where owner_email='mail.one@synthetic.test' and state='claimed'),'expiry updates at most 100 per call');
set local role authenticated;
select count(*) from public.list_mail_reviews();
reset role;
select pg_temp.expect(not exists(select 1 from private.mail_mutation_reviews where owner_email='mail.one@synthetic.test' and state='claimed'),'expired claims become uncertain, never reclaimed');
rollback;
